  const keys = Array.isArray(jwks.json.keys) ? jwks.json.keys : [];
  const key = keyFromJwks(jwks.json, SIGNING_KEY_ID);
  ctx.out.line(`key set  ${client.base}${JWKS_PATH}`);
  ctx.out.line(
    keys.length
      ? `key      ${keys.map((k) => `${k.kid} (${k.crv})`).join(", ")}`
      : "key      none published",
  );
